"""Simulate which response tokens land in the *second* Ulysses shard (SP rank 1) of
each packed micro-batch in the old-log-prob pass vs. the update pass, using the
same packing logic as the recorded run (balance_batch tent ordering + KK partitions
+ dynamic token budget). Self-contained port of verl's karmarkar_karp / ordering.
"""
import heapq
import math
import random
import sys


def karmarkar_karp(seqlen_list, k_partitions, equal_size):
    class Set:
        def __init__(self):
            self.sum = 0
            self.items = []

        def add(self, idx, val):
            self.items.append((idx, val))
            self.sum += val

        def merge(self, other):
            for idx, val in other.items:
                self.items.append((idx, val))
                self.sum += val

        def __lt__(self, other):
            if self.sum != other.sum:
                return self.sum < other.sum
            if len(self.items) != len(other.items):
                return len(self.items) < len(other.items)
            return self.items < other.items

    class State:
        def __init__(self, items, k):
            self.k = k
            self.sets = [Set() for _ in range(k)]
            for i, (idx, seqlen) in enumerate(items):
                self.sets[i].add(idx=idx, val=seqlen)
            self.sets = sorted(self.sets, reverse=True)

        def get_partitions(self):
            return [[idx for idx, _ in s.items] for s in self.sets]

        def merge(self, other):
            for i in range(self.k):
                self.sets[i].merge(other.sets[self.k - 1 - i])
            self.sets = sorted(self.sets, reverse=True)

        @property
        def spread(self):
            return self.sets[0].sum - self.sets[-1].sum

        def __lt__(self, other):
            if self.spread != other.spread:
                return self.spread > other.spread
            return self.sets[0] > other.sets[0]

    sorted_seqlen_list = sorted([(seqlen, i) for i, seqlen in enumerate(seqlen_list)])
    states_pq = []
    if equal_size:
        for offset in range(0, len(sorted_seqlen_list), k_partitions):
            items = [(sorted_seqlen_list[offset + i][1], sorted_seqlen_list[offset + i][0]) for i in range(k_partitions)]
            heapq.heappush(states_pq, State(items=items, k=k_partitions))
    else:
        for seqlen, idx in sorted_seqlen_list:
            heapq.heappush(states_pq, State(items=[(idx, seqlen)], k=k_partitions))
    while len(states_pq) > 1:
        s0 = heapq.heappop(states_pq)
        s1 = heapq.heappop(states_pq)
        s0.merge(s1)
        heapq.heappush(states_pq, s0)
    return states_pq[0].get_partitions()


def balanced_partitions(vals, k, equal_size):
    parts = karmarkar_karp(vals, k, equal_size)
    return [sorted(p) for p in parts]


def workload(L):
    return 24576 * L + L * L


MAX_TOKEN_LEN = 10240 * 2  # max_token_len_per_gpu * sp_size
SP = 2


def shard_flags(order, seqs):
    """order: list of sequence ids in micro-batch order (index-sorted). Returns, for each seq,
    a list of booleans per *response token* telling whether its log-prob is produced on SP rank 1
    (i.e. lives in the second half of the packed micro-batch after the -1 roll)."""
    L = sum(seqs[s][0] + seqs[s][1] for s in order)
    L_pad = L + (-L) % SP
    T = L_pad // SP
    flags = {}
    pos = 0
    for s in order:
        p, r = seqs[s]
        # response tokens occupy positions [pos+p, pos+p+r); their log-prob index is position-1
        flags[s] = [((pos + p + j) - 1) >= T for j in range(r)]
        pos += p + r
    return flags


def micro_batches_for(ids, seqs, num_mb):
    vals = [workload(seqs[s][0] + seqs[s][1]) for s in ids]
    parts = balanced_partitions(vals, num_mb, equal_size=False)
    return [[ids[i] for i in part] for part in parts]  # ids already index-ordered → sorted


def simulate(seed, m_nats=15.0):
    rnd = random.Random(seed)
    seqs = {}
    sid = 0
    for g in range(128):
        p = int(min(525, max(114, rnd.gauss(288, 70))))
        for _ in range(8):
            r = int(min(4096, max(98, math.exp(rnd.gauss(math.log(300), 0.6)))))
            seqs[sid] = (p, r)
            sid += 1
    # balance_batch across dp_size=2 with tent ordering
    wl = [workload(seqs[s][0] + seqs[s][1]) for s in range(1024)]
    parts = balanced_partitions(wl, 2, equal_size=True)
    ranks = []
    for part in parts:
        part = sorted(part, key=lambda x: (wl[x], x))
        ranks.append(part[::2] + part[1::2][::-1])
    # old pass: per rank, all 512 seqs; same num micro-batches across dp (max)
    tot = [sum(seqs[s][0] + seqs[s][1] for s in rk) for rk in ranks]
    n_old = max(math.ceil(t / MAX_TOKEN_LEN) for t in tot)
    old_flags = {}
    for rk in ranks:
        ids = list(range(len(rk)))  # local index order == tent order
        for mb in micro_batches_for(ids, {i: seqs[rk[i]] for i in ids}, n_old):
            fl = shard_flags(mb, {i: seqs[rk[i]] for i in mb})
            for i, f in fl.items():
                old_flags[rk[i]] = f
    # new pass: 4 mini-batches of 128 (in order), each packed separately; num mb = max over dp
    new_flags = {}
    new_mb_groups = []  # list of (list of seq ids) per micro-batch, for metric aggregation
    for k in range(4):
        subs = [rk[128 * k : 128 * (k + 1)] for rk in ranks]
        n_new = max(math.ceil(sum(seqs[s][0] + seqs[s][1] for s in sub) / MAX_TOKEN_LEN) for sub in subs)
        for sub in subs:
            ids = list(range(len(sub)))
            local = {i: seqs[sub[i]] for i in ids}
            for mb in micro_batches_for(ids, local, n_new):
                fl = shard_flags(mb, {i: local[i] for i in mb})
                for i, f in fl.items():
                    new_flags[sub[i]] = f
                new_mb_groups.append([sub[i] for i in mb])
    # token-level classification over response tokens
    nA = nB = nC = nD = 0
    for s in seqs:
        for o, n in zip(old_flags[s], new_flags[s]):
            if not o and not n:
                nA += 1
            elif not o and n:
                nB += 1
            elif o and not n:
                nC += 1
            else:
                nD += 1
    tot_tok = nA + nB + nC + nD
    # metric as logged: mean over micro-batches of per-micro-batch masked mean of (old-new)
    per_mb = []
    for grp in new_mb_groups:
        vals = []
        for s in grp:
            for o, n in zip(old_flags[s], new_flags[s]):
                vals.append(m_nats if (not o and n) else (-m_nats if (o and not n) else 0.0))
        per_mb.append(sum(vals) / len(vals))
    return dict(
        n_old=n_old,
        fracs=(nA / tot_tok, nB / tot_tok, nC / tot_tok, nD / tot_tok),
        corrupt_old=(nC + nD) / tot_tok,
        corrupt_new=(nB + nD) / tot_tok,
        ppo_kl_tokmean=m_nats * (nB - nC) / tot_tok,
        ppo_kl_mbmean=sum(per_mb) / len(per_mb),
    )


if __name__ == "__main__":
    seeds = int(sys.argv[1]) if len(sys.argv) > 1 else 10
    tm, mm = [], []
    for sd in range(seeds):
        r = simulate(sd)
        tm.append(r["ppo_kl_tokmean"])
        mm.append(r["ppo_kl_mbmean"])
        print(
            f"seed {sd}: n_old_mb={r['n_old']} A/B/C/D={['%.3f' % x for x in r['fracs']]} "
            f"corrupt_old={r['corrupt_old']:.3f} corrupt_new={r['corrupt_new']:.3f} "
            f"ppo_kl(token-mean)={r['ppo_kl_tokmean']:+.3f} ppo_kl(mb-mean)={r['ppo_kl_mbmean']:+.3f}"
        )
    for name, arr in (("token-mean", tm), ("mb-mean", mm)):
        mu = sum(arr) / len(arr)
        sdv = math.sqrt(sum((x - mu) ** 2 for x in arr) / max(1, len(arr) - 1))
        print(f"{name}: mean={mu:+.3f} sd={sdv:.3f} min={min(arr):+.3f} max={max(arr):+.3f} positive={sum(x > 0 for x in arr)}/{len(arr)}")

