"""Extend sim_packing: model the *content* of the misaligned labels (prompt token vs response token)
and predict the logged actor/ppo_kl under a two-level log-prob model."""
import math, random, sys
sys.path.insert(0, '/tmp/ptd_diag')
from sim_packing import balanced_partitions, workload, MAX_TOKEN_LEN, SP, micro_batches_for

X = 0.4      # |log p(sampled token)|
PROMPT = 30.0  # |log p(prompt/image-pad token as a response continuation)| (clamped to 20 in diffs)
RESP = float(sys.argv[2]) if len(sys.argv) > 2 else 10.0  # |log p(random response token)|

def pack(order, seqs):
    """Return per-seq list of (corrupted?, label_type) per response token.
    label_type in {'x' (own token), 'p' (prompt tok of another position), 'r' (response tok), 'pad'}."""
    L = sum(seqs[s][0] + seqs[s][1] for s in order)
    L_pad = L + (-L) % SP
    T = L_pad // SP
    # type of token at each packed position
    types = []
    for s in order:
        p, r = seqs[s]
        types += ['p'] * p + ['r'] * r
    types += ['pad'] * (L_pad - L)
    out = {}
    pos = 0
    for s in order:
        p, r = seqs[s]
        lst = []
        for j in range(r):
            q = pos + p + j - 1  # log-prob index for this response token
            if q >= T:
                lab = q - T + 1  # rank-1 uses rolled_labels[q-T] = input_ids[q-T+1]
                lst.append((True, types[lab] if lab < L_pad else 'pad'))
            else:
                lst.append((False, 'x'))
        out[s] = lst
        pos += p + r
    return out

def logp_abs(t):
    return {'x': X, 'p': PROMPT, 'r': RESP, 'pad': PROMPT}[t]

def contribution(old, new):
    (o, to), (n, tn) = old, new
    # diff = log p_new(label_new) - log p_old(label_old); ppo_kl adds -clamp(diff, -20, 20)
    diff = -logp_abs(tn) + logp_abs(to)
    diff = max(-20.0, min(20.0, diff))
    return -diff

def simulate(seed):
    rnd = random.Random(seed)
    seqs = {}
    sid = 0
    for g in range(128):
        p = int(min(525, max(114, rnd.gauss(288, 70))))
        for _ in range(8):
            r = int(min(4096, max(98, math.exp(rnd.gauss(math.log(300), 0.6)))))
            seqs[sid] = (p, r); sid += 1
    wl = [workload(seqs[s][0] + seqs[s][1]) for s in range(1024)]
    parts = balanced_partitions(wl, 2, equal_size=True)
    ranks = []
    for part in parts:
        part = sorted(part, key=lambda x: (wl[x], x))
        ranks.append(part[::2] + part[1::2][::-1])
    tot = [sum(seqs[s][0] + seqs[s][1] for s in rk) for rk in ranks]
    n_old = max(math.ceil(t / MAX_TOKEN_LEN) for t in tot)
    old = {}
    for rk in ranks:
        ids = list(range(len(rk))); local = {i: seqs[rk[i]] for i in ids}
        for mb in micro_batches_for(ids, local, n_old):
            for i, f in pack(mb, local).items():
                old[rk[i]] = f
    new = {}; groups = []
    for k in range(4):
        subs = [rk[128*k:128*(k+1)] for rk in ranks]
        n_new = max(math.ceil(sum(seqs[s][0] + seqs[s][1] for s in sub) / MAX_TOKEN_LEN) for sub in subs)
        for sub in subs:
            ids = list(range(len(sub))); local = {i: seqs[sub[i]] for i in ids}
            for mb in micro_batches_for(ids, local, n_new):
                for i, f in pack(mb, local).items():
                    new[sub[i]] = f
                groups.append([sub[i] for i in mb])
    per_mb = []
    tot_c = 0.0; tot_n = 0
    for grp in groups:
        vals = [contribution(o, n) for s in grp for o, n in zip(old[s], new[s])]
        per_mb.append(sum(vals) / len(vals)); tot_c += sum(vals); tot_n += len(vals)
    # label-pool composition diagnostics
    def pool(flags):
        c = {'p': 0, 'r': 0, 'pad': 0}
        for s in flags:
            for cor, t in flags[s]:
                if cor: c[t] += 1
        tot = sum(c.values()); return {k: v / tot for k, v in c.items()}
    return sum(per_mb) / len(per_mb), tot_c / tot_n, pool(old), pool(new)

if __name__ == '__main__':
    seeds = int(sys.argv[1]) if len(sys.argv) > 1 else 10
    res = []
    for sd in range(seeds):
        mb, tok, po, pn = simulate(sd)
        res.append(mb)
        print(f"seed {sd}: predicted ppo_kl (mb-mean)={mb:+.3f} (token-mean)={tok:+.3f} | wrong-label pool old: p={po['p']:.2f} r={po['r']:.2f} | new: p={pn['p']:.2f} r={pn['r']:.2f}")
    mu = sum(res)/len(res); sdv = math.sqrt(sum((x-mu)**2 for x in res)/max(1,len(res)-1))
    print(f"RESP={RESP}: predicted ppo_kl mean={mu:+.3f} sd={sdv:.3f} min={min(res):+.3f} max={max(res):+.3f} positive={sum(x>0 for x in res)}/{len(res)}")
